Cada adorn_*() agrega una capa: totales, porcentajes por columna, formato y los N entre paréntesis.

case_when() con ingresos


casen_proc_na &lt;- casen_proc_na |&gt;
  mutate(
    tramo_ingreso = case_when(
      ingreso &lt; 300000 ~ "Bajo",
      ingreso &lt; 700000 ~ "Medio",
      .default         = "Alto"
    ) |&gt;
      factor(levels = c("Bajo", "Medio", "Alto"),
             ordered = TRUE)
  )

frq(casen_proc_na$tramo_ingreso)


